  // js/fullscreen.js
  var AUTO_FULLSCREEN_STORAGE_KEY = "pokekukoro_auto_fullscreen";
  var autoFullscreenEnabled = false;
  function loadAutoFullscreenPref() {
    try {
      autoFullscreenEnabled = localStorage.getItem(AUTO_FULLSCREEN_STORAGE_KEY) === "1";
    } catch (e) {
      autoFullscreenEnabled = false;
    }
    return autoFullscreenEnabled;
  }
  function isAutoFullscreenEnabled() {
    return autoFullscreenEnabled;
  }
  function setAutoFullscreen(enabled) {
    autoFullscreenEnabled = !!enabled;
    try {
      localStorage.setItem(AUTO_FULLSCREEN_STORAGE_KEY, autoFullscreenEnabled ? "1" : "0");
    } catch (e) {
    }
  }
  var sceneFallbackEl = null;
  function getSceneFallbackElement() {
    return sceneFallbackEl;
  }
  function setSceneFallbackElement(el) {
    sceneFallbackEl = el;
  }
  function pruneStaleFallback() {
    if (sceneFallbackEl && !sceneFallbackEl.isConnected) {
      sceneFallbackEl = null;
      document.body.classList.remove("fs-fallback-lock");
    }
  }
  function currentFullscreenElement() {
    const native = document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement;
    if (native) return native;
    pruneStaleFallback();
    return sceneFallbackEl || null;
  }
  var FS_SPRITE_SCALE_SELECTOR = ".zor-field-outer";
  var ZOR_MAP_BG_NATURAL_W = 1376;
  var ZOR_MAP_BG_NATURAL_H = 768;
  var spriteScaleObserver = null;
  var spriteScaleEl = null;
  var spriteScaleBaseline = null;
  function zorMapCoverScale(w, h) {
    return Math.max(w / ZOR_MAP_BG_NATURAL_W, h / ZOR_MAP_BG_NATURAL_H);
  }
  function startFullscreenSpriteScale(sceneEl) {
    const field = sceneEl.matches(FS_SPRITE_SCALE_SELECTOR) ? sceneEl : sceneEl.querySelector(FS_SPRITE_SCALE_SELECTOR);
    if (!field) return;
    const rect = field.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    stopFullscreenSpriteScale();
    spriteScaleEl = field;
    spriteScaleBaseline = { coverScale: zorMapCoverScale(rect.width, rect.height) };
    spriteScaleObserver = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry || !spriteScaleBaseline) return;
      const { width, height } = entry.contentRect;
      if (!width || !height) return;
      const scale = zorMapCoverScale(width, height) / spriteScaleBaseline.coverScale;
      field.style.setProperty("--zor-sprite-scale", Math.max(1, scale).toFixed(4));
    });
    spriteScaleObserver.observe(field);
  }
  function stopFullscreenSpriteScale() {
    if (spriteScaleObserver) {
      spriteScaleObserver.disconnect();
      spriteScaleObserver = null;
    }
    if (spriteScaleEl) {
      spriteScaleEl.style.removeProperty("--zor-sprite-scale");
      spriteScaleEl = null;
    }
    spriteScaleBaseline = null;
  }
  function enterFallbackFullscreen(sceneEl) {
    setSceneFallbackElement(sceneEl);
    sceneEl.classList.add("fs-fallback");
    document.body.classList.add("fs-fallback-lock");
    document.dispatchEvent(new CustomEvent("scenefsfallbackchange"));
  }
  function exitFallbackFullscreen() {
    if (!sceneFallbackEl) return;
    sceneFallbackEl.classList.remove("fs-fallback");
    setSceneFallbackElement(null);
    document.body.classList.remove("fs-fallback-lock");
    document.dispatchEvent(new CustomEvent("scenefsfallbackchange"));
  }
  function hasRecentUserGesture() {
    return !navigator.userActivation || navigator.userActivation.isActive;
  }
  function requestSceneFullscreen(sceneEl, { auto = false } = {}) {
    if (!sceneEl) return;
    pruneStaleFallback();
    startFullscreenSpriteScale(sceneEl);
    const req = sceneEl.requestFullscreen || sceneEl.webkitRequestFullscreen || sceneEl.msRequestFullscreen;
    if (!req) {
      enterFallbackFullscreen(sceneEl);
      return;
    }
    if (auto && !hasRecentUserGesture()) {
      stopFullscreenSpriteScale();
      return;
    }
    let result;
    try {
      result = req.call(sceneEl);
    } catch (err) {
      if (!auto) enterFallbackFullscreen(sceneEl);
      else stopFullscreenSpriteScale();
      return;
    }
    if (result && typeof result.catch === "function") {
      result.catch(() => {
        if (!auto) enterFallbackFullscreen(sceneEl);
        else stopFullscreenSpriteScale();
      });
    }
  }
  function exitSceneFullscreen() {
    stopFullscreenSpriteScale();
    pruneStaleFallback();
    if (sceneFallbackEl) {
      exitFallbackFullscreen();
      return;
    }
    const exit = document.exitFullscreen || document.webkitExitFullscreen || document.msExitFullscreen;
    if (exit) exit.call(document);
  }
  function toggleSceneFullscreen(sceneEl) {
    if (!sceneEl) return;
    if (!currentFullscreenElement()) {
      requestSceneFullscreen(sceneEl);
    } else {
      exitSceneFullscreen();
    }
  }
  var fullscreenSizeLockEl = null;
  var fullscreenSizeLockBaseline = null;
  function clearFullscreenSizeLock() {
    if (!fullscreenSizeLockEl) return;
    fullscreenSizeLockEl.style.width = "";
    fullscreenSizeLockEl.style.height = "";
    fullscreenSizeLockEl.style.transform = "";
    fullscreenSizeLockEl.style.transformOrigin = "";
    fullscreenSizeLockEl = null;
    fullscreenSizeLockBaseline = null;
  }
  function applyFullscreenSizeLock() {
    const sceneEl = currentFullscreenElement();
    if (!sceneEl) {
      clearFullscreenSizeLock();
      return;
    }
    if (fullscreenSizeLockEl !== sceneEl) {
      clearFullscreenSizeLock();
      fullscreenSizeLockEl = sceneEl;
      fullscreenSizeLockBaseline = {
        w: window.innerWidth,
        h: window.innerHeight,
        dpr: window.devicePixelRatio || 1
      };
    }
    const base = fullscreenSizeLockBaseline;
    const currentDpr = window.devicePixelRatio || 1;
    const scale = base.dpr / currentDpr || 1;
    sceneEl.style.width = base.w + "px";
    sceneEl.style.height = base.h + "px";
    sceneEl.style.transform = `scale(${scale})`;
    sceneEl.style.transformOrigin = "top left";
  }
  ["fullscreenchange", "webkitfullscreenchange", "msfullscreenchange", "scenefsfallbackchange"].forEach((evt) => {
    document.addEventListener(evt, applyFullscreenSizeLock);
  });
  window.addEventListener("resize", applyFullscreenSizeLock);

  // js/utils.js
  function $(id) {
    return document.getElementById(id);
  }
  function showScreen(id) {
    document.querySelectorAll(".screen").forEach((s) => s.classList.remove("active"));
    $(id).classList.add("active");
  }
  function toast(msg, duration = 2500) {
    const t = document.createElement("div");
    t.className = "toast";
    t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(() => {
      t.classList.add("out");
      setTimeout(() => t.remove(), 300);
    }, duration);
  }
  function relocateModal() {
    const modal = $("modal");
    if (!modal) return;
    const target = currentFullscreenElement() || document.body;
    if (modal.parentElement !== target) target.appendChild(modal);
  }
  function showModal(title, body, actions = []) {
    relocateModal();
    $("modal-title").textContent = title;
    $("modal-body").innerHTML = body;
    const actionsEl = $("modal-actions");
    actionsEl.innerHTML = "";
    actions.forEach((a) => {
      const b = document.createElement("button");
      b.className = a.class || "btn-primary";
      b.textContent = a.label;
      b.onclick = () => {
        $("modal").classList.remove("show");
        a.onClick && a.onClick();
      };
      actionsEl.appendChild(b);
    });
    $("modal").classList.add("show");
  }
  function addScore(user, points) {
    state.scores[user] = (state.scores[user] || 0) + points;
  }
  function normalizeAnswer(s) {
    return String(s).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  }
  function getRanking() {
    return Object.entries(state.scores).map(([u, s]) => ({ user: u, score: s })).sort((a, b) => b.score - a.score);
  }
  function renderRanking(container, limit = 10, title = "\u{1F3C6} Ranking") {
    const ranking = getRanking().slice(0, limit);
    container.innerHTML = `<div class="ranking-title">${title}</div>`;
    if (ranking.length === 0) {
      container.innerHTML += '<p style="font-size:12px;color:var(--muted);text-align:center;padding:10px;">Sin puntuaciones a\xFAn</p>';
      return;
    }
    ranking.forEach((r, i) => {
      const row = document.createElement("div");
      row.className = "ranking-row" + (i === 0 ? " gold" : i === 1 ? " silver" : i === 2 ? " bronze" : "");
      row.innerHTML = `
      <span class="ranking-pos">${i + 1}</span>
      <span class="ranking-name">@${r.user}</span>
      <span class="ranking-score">${r.score} pts</span>
    `;
      container.appendChild(row);
    });
  }

