      const who2 = targetsOther ? `@${targetUser}` : `${user}`;
      addChatMessage(null, `${who2}: solo te quedan ${available} mejora${available === 1 ? "" : "s"} pendiente${available === 1 ? "" : "s"} en el Nivel ${ms.bossLevel} (pediste ${requestedTotal}).`, "system");
