    const hpText = `${Math.max(0, currentHp)}/${stats.maxHp}`;
    const available = bossLevelUpsAvailable(ms, player);
    const availableText = available > 0 ? ` \xB7 Mejoras pendientes: ${available}` : "";
    addChatMessage(null, `\u{1F4CA} @${user} (${player.pokemon.name}) \xB7 Nivel ${ms.bossLevel} \xB7 Ataque: ${stats.atk} \xB7 Vida: ${hpText} \xB7 Velocidad: ${speedPct}% m\xE1s r\xE1pido que la base${availableText}`, "system");
