      // Usuarios expulsados del lobby por el streamer: no pueden volver a
      // apuntarse en ESTA partida (se resetea al llamar de nuevo a
      // startSafari(), es decir, al empezar una nueva partida).
      expelledUsers: /* @__PURE__ */ new Set(),
      lobbyExpelPopoverUser: null,
      // usuario cuyo popover "Expulsar" está abierto en el lobby (null si ninguno)
      lobbyExpelPopoverEl: null,
      fieldSprites: {},
      // user -> { el, sprite } — sprites PMD sobre el terreno
      tickInterval: null,
      lastTick: null,
      aiming: false,
