    ms.roundSpawnGoal = minP + Math.floor(Math.random() * (maxP - minP + 1));
    ms.roundSpawned = 0;
    ms.roundCrossingWindowMs = getVistaLinceCrossingWindowMs(ms.round);
    ms.crossingStartTime = null;
    ms.roundLog = [];
    ms.crossers = {};
    ms.guesses = {};
