    banner.id = "zor-victory-banner";
    banner.innerHTML = `
    <div class="win-title pixel">${escapeHtml(title)}</div>
    <div class="zor-victory-wolves" id="zor-victory-wolves"></div>
    <div class="mode-end-actions">
      <button class="zor-start-btn" id="zor-victory-again-btn">\u{1F501} Nueva Partida</button>
      <button class="mode-end-menu-btn" id="zor-victory-menu-btn">\u{1F3E0} Men\xFA Principal</button>
    </div>
  `;
    field.appendChild(banner);
