        addChatMessage(null, `\u{1F52A} El pueblo decide: \xA1S\xCD gana (${counts.si}-${counts.no})! @${user} NO era un Zoroark: era inocente y queda eliminado/a igualmente.`, "wrong");
        playZorEliminated();
